<body><div id="game"><div class="sky"></div><div class="sun"></div><div class="mountain m1"></div><div class="mountain m2"></div><div class="walls"></div><div class="roof"></div><div class="ground"></div>
<div class="hud"><div class="fighter-hud"><div class="name">LIANG</div><div class="barframe"><div class="bar" id="hp1"></div></div></div><div><div class="timer" id="timer">60</div><div class="round">ROUND 1</div></div><div class="fighter-hud right"><div class="name">ROSHI</div><div class="barframe"><div class="bar" id="hp2"></div></div></div></div>
<div class="vs" id="vs">FIGHT!</div><canvas id="canvas"></canvas>
<div class="controls"><div class="move"><button data-key="a">←</button><button data-key="d">→</button></div><div class="actions"><button data-action="punch">P</button><button data-action="kick">K</button></div></div>
<div class="overlay" id="overlay"><div class="panel"><p>A dual of discipline</p><h1>KUNG FU <em>MASTERS</em></h1><button id="start">ENTER THE ARENA</button></div></div></div>
<script>
const c=document.getElementById('canvas'),ctx=c.getContext('2d'),overlay=document.getElementById('overlay'),timerEl=document.getElementById('timer'),vs=document.getElementById('vs');
let w,h,started=false,ended=false,last=0,timeLeft=60,roundTime=0,keys={},hitFlash=0;
function resize(){w=c.width=innerWidth*devicePixelRatio;h=c.height=innerHeight*devicePixelRatio}addEventListener('resize',resize);resize();
function fighter(x,side){return{x,y:0,vy:0,hp:100,side,action:'idle',attack:0,cool:0,walk:0,hit:0,block:false}}
let p1=fighter(.28,1),p2=fighter(.72,-1);
const groundY=()=>h*.72;
function keyAttack(f,k){if(f.cool>0||ended)return;f.action=k;f.attack=.18;f.cool=.38}
addEventListener('keydown',e=>{keys[e.key.toLower]=true;if(e.key===' '||e.key==='Enter')keyAttack(p1,'punch');if(e.key.toLowerCase()==='j')keyAttack(p1,'punch');if(e.key.toLowerCase()==='k')keyAttack(p1,'kick')});
addEventListener('keyup',e=>keys[e.key.toLower]=false);
document.querySelectorAll('[data-key]').forEach(b=>{const k=b.dataset.key;b.onpointerdown=e=>{e.prevent;e.prevent;keys[k]=true};b.onpointerup=()=>keys[k]=false;b.onpointerleave=()=>keys[k]=false});
document.querySelectorAll('[data-action]').forEach(b=>b.onpointerdown=e=>{e.preventDefault();keyAttack(p1,b.dataset.action)});
document.getElementById('start').onclick=()=>{overlay.classList.add('hidden');started=true;ended=false;timeLeft=60;p1.hp=p2.hp=100;p1.x=.28;p2.x=.72;updateHP();vs.classList.add('show');setTimeout(()=>vs.classList.remove('show'),900)};
function updateHP(){document.getElementById('hp1').style.width=p1.hp+'%';document.getElementById('hp2').style.width=p2.hp+'%'}
function hit(a,b,damage){let dx=(b.x-a.x)*w,dy=0;if(Math.abs(dx)<w*.13&&a.attack>0.04&&a.action){b.hp=Math.max(0,b.hp-damage);b.hit=.18;b.vy=-7*devicePixelRatio;a.attack=0;a.cool=.18;updateHP();hitFlash=.12;if(b.hp<=0)end(a)}}
function end(winner){ended=true;setTimeout(()=>{document.querySelector('.panel p').textContent=winner===p1?'Liang wins':'Roshi wins';document.querySelector('.panel h1').innerHTML=winner===p1?'LIANG <em>VICTORIOUS</em>':'ROSHI <em>VICTORIOUS</em>';document.queryElementById&&0;overlay.querySelector('h1').innerHTML=winner===p1?'LIANG <em>VICTORIOUS</em>':'ROSHI <em>VICTORIOUS</em>';overlay.classList.remove('hidden')},700)}
function update(dt){if(!started||ended)return;roundTime+=dt;if(roundTime>=1){roundTime=0;timeLeft--;timerEl.textContent=timeLeft;if(timeLeft<=0){ended=true;end(p1.hp>=p2.hp?p1:p2)}}
 let speed=.23*dt;p1.block=keys.shift||false;if(keys.a)p1.x-=speed;if(keys.d)p1.x+=speed;p1.x=Math.max(.08,Math.min(p2.x-.09,p1.x));
 // simple enemy AI
 let diff=p2.x-p1.x;if(Math.abs(diff)>.13)p2.x-=Math.sign(diff)*(.10*dt);else if(Math.random()<.018)keyAttack(p2,Math.random()<.5?'punch':'kick');
 p2.x=Math.max(p1.x+.09,Math.min(.92,p2.x));
 for(const f of[p1,p2]){if(f.attack>0)f.attack-=dt;if(f.cool>0)f.cool-=dt;if(f.hit>0)f.hit-=dt}
 hit(p1,p2,p1.action==='kick'?12:8);hit(p2,p1,p2.action==='kick'?12:8); }
function limb(ctx,x,y,len,angle,width,color){ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.fillStyle=color;ctx.fillRect(-width/2,0,width,len);ctx.restore()}
function drawFighter(f){const sx=f.x*w,sy=groundY(),dir=f.side,flip=dir;ctx.save();ctx.translate(sx,sy);ctx.scale(flip,1);let bob=f.action==='idle'?Math.sin(performance.now()/180)*4:0;if(f.hit>0)ctx.translate(-10*devicePixelRatio,0);ctx.translate(0,bob);
 // shadow
 ctx.fillStyle='rgba(20,10,8,.28)';ctx.beginPath();ctx.ellipse(0,8*devicePixelRatio,75*devicePixelRatio,18*devicePixelRatio,0,0,Math.PI*2);ctx.fill();
 const s=devicePixelRatio;
 ctx.strokeStyle='#17151d';ctx.lineWidth=11*s;ctx.lineCap='round';
 // legs
 limb(ctx,-18*s,-58*s,90*s,.12,28*s,'#efe1bf');limb(ctx,18*s,-58*s,90*s,-.12,28*s,'#efe1bf');ctx.fillStyle='#17151d';ctx.fillRect(-44*s,15*s,48*s,15*s);ctx.fillRect(-4*s,15*s,48*s,15*s);
 // gi
 ctx.fillStyle=f===p1?'#b64331':'#d6b34e';ctx.beginPath();ctx.moveTo(-43*s,-115*s);ctx.quadraticCurveTo(0,-145*s,43*s,-115*s);ctx.lineTo(34*s,-58*s);ctx.quadraticCurveTo(0,-42*s,-34*s,-58*s);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#2a2525';ctx.fillRect(-38*s,-82*s,76*s,9*s);
 // belt
 ctx.strokeStyle='#17151d';ctx.lineWidth=9*s;ctx.beginPath();ctx.moveTo(-36*s,-67*s);ctx.lineTo(36*s,-67*s);ctx.stroke();
 // arms
 let arm= f.action==='punch'&&f.attack>0?-70*s:-25*s;let armAngle=f.action==='kick'?-.3:-.15;
 limb(ctx,-36*s,-108*s,70*s,-.7,18*s,'#edb58a');limb(ctx,36*s,-108*s,f.action==='punch'&&f.attack>0?98*s:70*s,f.action==='punch'&&f.attack>0?-.05: .7,18*s,'#edb58a');ctx.fillStyle='#edb58a';ctx.beginPath();ctx.arc(38*s,-108*s+(f.action==='punch'&&f.attack>0?arm:0),13*s,0,Math.PI*2);ctx.fill();
 // head
 ctx.fillStyle='#edb58a';ctx.beginPath();ctx.arc(0,-153*s,34*s,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#17151d';ctx.beginPath();ctx.arc(-5*s,-161*s,35*s,Math.PI,Math.PI*2);ctx.lineTo(28*s,-153*s);ctx.lineTo(-32*s,-153*s);ctx.fill();ctx.fillStyle='#17151d';ctx.fillRect(-10*s,-148*s,8*s,4*s);ctx.fillRect(8*s,-148*s,8*s,4*s);
 // headband
 ctx.fillStyle='#ed4a35';ctx.fillRect(-34*s,-166*s,68*s,8*s);ctx.beginPath();ctx.moveTo(-28*s,-159*s);ctx.lineTo(-55*s,-145*s);ctx.lineTo(-34*s,-170*s);ctx.fill();ctx.restore();}
function draw(){ctx.clearRect(0,0,w,h);ctx.save();ctx.scale(1,1);drawFighter(p1);drawFighter(p2);if(hitFlash>0){ctx.fillStyle=`rgba(255,240,180,${hitFlash*5})`;ctx.fillRect(0,0,w,h)}ctx.restore();hitFlash=Math.max(0,hitFlash-.016)}
function loop(ts){let dt=Math.min(.033,(ts-last)/1000||0);last=ts;update(dt);draw();requestAnimationFrame(loop)}requestAnimationFrame(loop);
</script></body></html>
